+}
+
+::deep .thread-link:hover {
+    text-decoration: underline;
+}
+
+::deep .message-actions {
+    position: absolute;
+    top: -8px;
+    right: 8px;
+    background: #2b2d31;
+    border: 1px solid #404249;
+    border-radius: 6px;
+    display: flex;
+    gap: 2px;
+    padding: 2px;
+    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
+}
+
+::deep .action-btn {
+    background: none;
+    border: none;
+    color: #b5bac1;
+    padding: 4px 8px;
+    border-radius: 4px;
+    cursor: pointer;
+    font-size: 0.75rem;
+    white-space: nowrap;
+}
+
+::deep .action-btn:hover {
+    background: #404249;
+    color: #f2f3f5;
+}
+
+::deep .emoji-picker-container {
+    position: relative;
+}
+
+::deep .emoji-picker {
