+::deep .message-input-area,
+::deep .thread-input-area {
+    padding: 12px 16px;
+    border-top: 1px solid #1e1f22;
+    display: flex;
+    gap: 8px;
+    align-items: flex-end;
+    flex-shrink: 0;
+}
+
+::deep .message-textarea {
+    flex: 1;
+    background: #383a40;
+    border: none;
+    border-radius: 8px;
+    padding: 10px 12px;
+    color: #dbdee1;
+    font-size: 0.9rem;
+    resize: none;
+    min-height: 40px;
+    max-height: 120px;
+    font-family: inherit;
