+    cursor: pointer;
+    font-size: 0.85rem;
+    white-space: nowrap;
+}
+
+::deep .send-btn:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+::deep .send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread Panel */
+::deep .thread-panel {
+    background: #2b2d31;
+    color: #dbdee1;
+    display: flex;
+    flex-direction: column;
+    border-left: 1px solid #1e1f22;
+    overflow: hidden;
+}
+
+::deep .thread-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 12px 16px;
+    border-bottom: 1px solid #1e1f22;
+    flex-shrink: 0;
+}
+
+::deep .thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #f2f3f5;
+}
+
+::deep .close-btn {
+    background: none;
+    border: none;
+    color: #b5bac1;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+::deep .close-btn:hover {
+    background: #404249;
+    color: #f2f3f5;
+}
+
+::deep .thread-root-message {
+    padding: 12px 16px;
+    background: #232428;
+    border-bottom: 1px solid #1e1f22;
+    flex-shrink: 0;
+}
+
+::deep .thread-root-message .message-content {
+    margin-top: 4px;
+    color: #949ba4;
+    font-size: 0.85rem;
+}
+
+::deep .thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+}
+
+::deep .thread-reply {
+    padding: 8px 0;
+    border-bottom: 1px solid #383a40;
+}
+
+::deep .thread-reply:last-child {
+    border-bottom: none;
+}
